using DriveOS.Application.Abstractions.Messaging;using DriveOS.Application.Abstractions.Time;using DriveOS.Modules.CurriculumPedagogy.Application.Persistence;using DriveOS.Modules.CurriculumPedagogy.Domain.Curricula;using DriveOS.Modules.CurriculumPedagogy.Domain.LicenseCategories;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.CurriculumPedagogy.Application.Curricula;
internal sealed class CreateCurriculumCommandHandler(ICurriculumRepository repo,ILicenseCategoryDefinitionRepository categories,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<CreateCurriculumCommand,CurriculumId>{public async Task<Result<CurriculumId>> Handle(CreateCurriculumCommand c,CancellationToken ct){if(await repo.ExistsByCodeAsync(c.OrganizationId,c.Code,ct))return Result.Failure<CurriculumId>(CurriculumErrors.CodeAlreadyExists);var category=await categories.GetActiveByScopeAsync(c.OrganizationId,c.CountryCode,c.LicenseCategoryCode,ct);if(category is null)return Result.Failure<CurriculumId>(LicenseCategoryDefinitionErrors.NotFound);var r=Curriculum.Create(CurriculumId.New(),c.OrganizationId,c.Code,c.Name,c.Description,c.CountryCode,c.LicenseCategoryCode);if(r.IsFailure)return Result.Failure<CurriculumId>(r.Error);r.Value.SetCreatedAudit(clock.UtcNow,c.ActorUserId);await repo.AddAsync(r.Value,ct);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
internal sealed class CreateCurriculumVersionCommandHandler(ICurriculumRepository repo,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<CreateCurriculumVersionCommand,CurriculumVersionId>{public async Task<Result<CurriculumVersionId>> Handle(CreateCurriculumVersionCommand c,CancellationToken ct){var x=await repo.GetByIdForUpdateAsync(c.CurriculumId,ct);if(x is null||x.OrganizationId!=c.OrganizationId)return Result.Failure<CurriculumVersionId>(CurriculumErrors.NotFound);var r=x.CreateVersion(CurriculumVersionId.New(),c.EffectiveFrom,c.EffectiveTo,c.ChangeSummary,c.ActorUserId,clock.UtcNow);if(r.IsFailure)return Result.Failure<CurriculumVersionId>(r.Error);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
internal sealed class AddCurriculumModuleCommandHandler(ICurriculumRepository repo,ICurriculumPedagogyUnitOfWork uow):ICommandHandler<AddCurriculumModuleCommand,CurriculumModuleId>{public async Task<Result<CurriculumModuleId>> Handle(AddCurriculumModuleCommand c,CancellationToken ct){var x=await repo.GetByIdForUpdateAsync(c.CurriculumId,ct);if(x is null||x.OrganizationId!=c.OrganizationId)return Result.Failure<CurriculumModuleId>(CurriculumErrors.NotFound);var r=x.AddModule(c.VersionId,CurriculumModuleId.New(),c.Code,c.Name,c.Description,c.Order);if(r.IsFailure)return Result.Failure<CurriculumModuleId>(r.Error);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
internal sealed class AddCompetencyCommandHandler(ICurriculumRepository repo,ICurriculumPedagogyUnitOfWork uow):ICommandHandler<AddCompetencyCommand,CompetencyId>{public async Task<Result<CompetencyId>> Handle(AddCompetencyCommand c,CancellationToken ct){var x=await repo.GetByIdForUpdateAsync(c.CurriculumId,ct);if(x is null||x.OrganizationId!=c.OrganizationId)return Result.Failure<CompetencyId>(CurriculumErrors.NotFound);var r=x.AddCompetency(c.VersionId,c.ModuleId,CompetencyId.New(),c.Code,c.Name,c.Description,c.LearningObjective,c.Order,c.IsRequired);if(r.IsFailure)return Result.Failure<CompetencyId>(r.Error);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
internal sealed class PublishCurriculumVersionCommandHandler(ICurriculumRepository repo,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<PublishCurriculumVersionCommand>{public async Task<Result> Handle(PublishCurriculumVersionCommand c,CancellationToken ct){var x=await repo.GetByIdForUpdateAsync(c.CurriculumId,ct);if(x is null||x.OrganizationId!=c.OrganizationId)return Result.Failure(CurriculumErrors.NotFound);var r=x.PublishVersion(c.VersionId,c.ActorUserId,clock.UtcNow);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
